#include <stdio.h>
#include <string.h>
#include <stdbool.h>

/* Copy src into dst of capacity cap; report truncation. */
bool copy_str(char *dst, size_t cap, const char *src) {
    if (cap == 0) return false;
    int n = snprintf(dst, cap, "%s", src);    /* always terminates. */
    return n >= 0 && (size_t)n < cap;          /* false: truncated. */
}

int main(void) {
    char line[32];
    if (fgets(line, sizeof line, stdin) == NULL) return 1;
    line[strcspn(line, "\n")] = '\0';            /* remove optional newline. */

    char name[8];
    if (!copy_str(name, sizeof name, line))
        puts("Name too long, truncated.");
    printf("[%s] length %zu\n", name, strlen(name));
    return 0;
}
